from pathlib import Path
import json
R=Path(__file__).resolve().parent
q=json.loads((R/'benchmark-v5/questions.json').read_text());a=json.loads((R/'benchmark-v5/answer-key.json').read_text());old=json.loads(json.dumps(a));q['benchmark_version']=a['benchmark_version']='benchmark-v6'
q['scope']='Original Nemesis basic board standard semi-cooperative core, original 28-page manual plus official FAQ v2.2 (16.04.2025) base-game sections. Optional modes/boards and expansions excluded.'
fixes={
'Q04':('At end of own round take 1 Light Wound. Passing bars normal Actions this Player Phase, but official FAQ permits Interruption after passing. May discard any number of hand cards on passing. No further Fire wounds from later players rounds this turn.','Rules 21'),
'Q19':('Use corresponding Evacuation Room Action cost 2, unlocked Pod with free space, no Intruder/Malfunction. Roll Noise first and fail if Intruder reaches Room. Two Character spaces; Heavy Objects use none. Enter then launch immediately or wait and pass current turn. At start of first round next Player Phase choose wait/pass, launch, or free exit followed by a full two-Action round. Intruder appearing in Section returns all Pod occupants; another boarder may immediately launch.','Rules 1-3'),
'Q25':('Larva removed to token pool, add Adult; Creeper removed to pool, add Breeder. Adult/Breeder cause ordered Noise rolls excluding Combat; token returns. For Adult specifically, return token immediately BEFORE Noise so same token may be redrawn in an Encounter. Queen: Characters in Nest means Queen there and Encounter; otherwise including undiscovered Nest add Egg; return Queen. Fully resolve triggered effects before new turn.','Rules 7,19'),
'Q30':('Search Action: choose one matching Red/Yellow/Green deck, white may choose any ONE, draw two, keep one, put rejected card at BOTTOM of same deck, not shuffle. Lower counter one, zero prevents Search except e.g. Scavenging; Special Rooms cannot Search. Blue Items only Craft.','Actions 6,15'),
'Q39':('Start marker first green; advance with Time. Stop removes it, restart green. First yellow irreversible/unlocks all Pods, which can relock; subsequent yellow spaces do NOT re-unlock them. Skull or jump with active sequence destroys ship. Characters cannot initiate sequence with anyone hibernating, but Coolant Leak Event can start it despite sleepers.','Rules 14,20,25'),
'Q55':('Sharing Room with Intruder defines Combat, not Eggs. In Combat Only requires it, Out of Combat Only requires none. Unmarked card/Item actions can be used in either subject to requirements; Basic Actions in Combat are limited to Shoot, Melee and Basic Movement as Escape. No Room Actions or Quest activation in Combat.','Actions 3-5'),
}
for e in a['answers']:
 if e['id'] in fixes:
  e['expected_answer'],label=fixes[e['id']];e['source_references'].append({'path':'nemesis-current-official-faq.pdf','section_questions':label,'printed_pages':[2,3,4]});e['source_correction']='Current official FAQ supersedes/clarifies original manual wording; source expansion explicitly versioned.'
extra=[
('While waiting in an Escape Pod, must you roll Noise when Adult bag development calls for it?', 'Yes. Waiting Character is treated as present in the corresponding Room and rolls Noise.', 'Rules 1','pod-wait-noise'),
('A Malfunction is placed in the Evacuation Section while you are already waiting in its Pod. Can you launch, wait or exit, and what does that Malfunction prevent?', 'May still launch, wait or exit; Malfunction only prevents using Room Action to ENTER Pods.', 'Rules 3','pod-wait-malfunction'),
('When Escaping from several differently sized Intruders, how many attacks and in what order?', 'One Attack per Intruder, starting with larger ones: Queen, Breeder, Adult, Larva (decreasing size).', 'Rules 5','escape-attack-order'),
('An Event instructs removing itself from the game but its other effect cannot be resolved. Is it removed?', 'Yes, remove it even if its other content cannot resolve.', 'Rules 6','event-removal'),
('When Adult bag development triggers Noise, when does the drawn Adult token return, and may a triggered Encounter draw that very token?', 'Return immediately BEFORE Noise rolls; yes it may be drawn again during an Encounter.', 'Rules 7','bag-return-timing'),
('A retreating Intruder meets a Closed Door. What happens normally, and what changes under The Way of Moving Weakness for an affected non-Breeder/non-Queen?', 'Normally destroys Door and stays in Room; with that Weakness for an affected Intruder other than Breeder/Queen nothing happens at all.', 'Rules 8','retreat-door-weakness'),
('Does the Hand Serious Wound increase the cost of Basic Shoot, and why?', 'No. Shoot is a Basic Action, not an Item Action.', 'Rules 9','hand-wound-shoot'),
('With Vulnerability to Fire discovered, how much extra Injury applies per damage instance, and how many Injuries for a Flamethrower double-crosshair hit?', 'One extra per damage instance, x+1; this hit causes 3 Injuries, not one bonus per separate Injury.', 'Rules 11','fire-weakness'),
('A Larva attacks a Character who already has a Larva on their board. What happens to each Larva and to the Character?', 'Attacking Larva disappears; existing board Larva stays; Character gets one Contamination card, no automatic death from this attack alone.', 'Rules 12','second-larva-attack'),
('After a Character hibernates, Fire appears in the Hibernatorium. Does the sleeper take Fire wounds and what can still kill them?', 'No Fire wounds; treated out of play. Ship destruction can still kill sleeper; endgame survival checks remain applicable.', 'Rules 13','sleeper-fire'),
('Can the Coolant Leak Event start Self-Destruct while someone hibernates, and how does that differ from starting it as a Character?', 'Yes, Event can; Character initiation is prohibited while anyone hibernates.', 'Rules 14','coolant-leak'),
('Where do discarded/dead Intruder tokens go, and can they be reused later?', 'Unused token pool, not removed from game; may be reused for bag additions or a matching Intruder entering ducts.', 'Rules 19','intruder-token-pool'),
('Can Fire and Malfunction markers be placed in unexplored Rooms?', 'Fire yes; Malfunction no.', 'Rules 22','unexplored-markers'),
('A Character with two Light Wounds receives two more Light Wounds. What Wounds remain after resolving them?', 'One Serious Wound from third Light plus one Light Wound remaining from fourth.', 'Rules 23','multiple-light-wounds'),
('On a Character death in standard play, what happens to Heavy Objects versus their Item cards?', 'Heavy Objects (Corpse/Carcass/Egg) drop in Room; Items disappear from game rather than becoming dropped Objects. Cooperative item retention excluded.', 'Rules 24','dead-items'),
('Self-Destruct reaches its first yellow space, Pods unlock, then are relocked. Does reaching the next yellow space unlock them again?', 'No; later yellow spaces do not re-unlock. Unlock manually.', 'Rules 25','yellow-reunlock'),
('Does destroying the ship fulfill Objectives to kill the Queen or destroy the Nest; does that alone make your Character a winner?', 'Yes fulfills those destruction/kill requirements; Character must still survive and satisfy all own Objective requirements.', 'Rules 26','destruction-objectives'),
('May you intentionally spend an empty Trade Action with no intention of exchange; what if honest negotiations end without a trade?', 'Empty Actions that do not meaningfully change game state should be disallowed, including deliberately empty Trade. Honest negotiations may result in no Items traded.', 'Actions 2','empty-actions'),
('What kind of Action activates a Quest Item, may it be done in Combat, and does a Room Malfunction prevent it?', 'Basic Action printed on quest card, forbidden in Combat; Room Malfunction does not prevent activation.', 'Actions 3; Items 10','quest-activation'),
('Which Basic Actions can be used in Combat; can you Trade, Craft or Pick Up an Object there? What about permitted card or Item Actions?', 'Only Basic Shoot, Melee, or Basic Movement as Escape. No Trade/Craft/PickUp, no Room Action or Quest activation. Card/Item actions without Out of Combat restriction may be used subject to own requirements.', 'Actions 4-5','combat-basic-exceptions'),
('Can Soldier use Covering Fire only on themselves, and how are direction, Noise and Surprise targeting handled when moving two Characters?', 'May use for self alone. Both move in direction of their choice, perform one Noise roll; if Encounter, Surprise Attack check is for Soldier.', 'Actions 7','covering-fire'),
('How does Full Auto calculate damage and consume Ammo?', 'Remove all Ammo, then one Shoot Action. Add Shoot Injuries plus discarded Ammo divided by two rounded down, plus 1 for Assault Rifle bonus.', 'Actions 8','full-auto'),
('When can Nerves of Steel be chosen relative to seeing the Attack card, and may it protect you when another Character triggered a Surprise Attack?', 'May see Attack card before using it. May use when someone else triggers Surprise but only Soldier benefits; e.g. Frenzy still affects others.', 'Actions 9-10','nerves-of-steel'),
('Careful Movement or Reconnaissance reveals a Danger/Silence Exploration token. Does that automatic result apply or the movement ability?', 'Careful Movement result applies instead; cancels Noise roll and automatic Danger/Silence Exploration results. Reconnaissance also cancels both.', 'Actions 11','careful-exploration-priority'),
('May Captain use Order while personally in Combat; may Intercom force someone else to Move out of Combat and what rules apply?', 'Captain cannot use Order while in Combat. Through Intercom can force another Character to Move out of Combat with normal Escape rule.', 'Actions 12','order-escape'),
('Who can draw an Action card when Captain uses Motivation with active Intercom?', 'All Characters in Rooms with a Computer and all Characters in Captain Room.', 'Actions 13','motivation-intercom'),
('Moving via Technical Corridors card or Plans Item reveals a Door Exploration token. Where does the Door go?', 'Ignore Door token effect because entry direction cannot be determined.', 'Actions 14','technical-door-exploration'),
('Can you Interrupt a Captain Order played remotely via Intercom when you are not in the Captain Room; does passing bar playing Interruption?', 'No remote Interruption: must share Room with Character performing Action. Passing does not bar playing Interruption.', 'Actions 17; Rules 21','interruption-exceptions'),
('After two Actions your hand is empty. Do you automatically pass then, and what timing consequence can Fire or Bleeding have?', 'No automatic pass. Wait for next round to pass; can suffer Fire/Bleeding again because passing ends another round.', 'Actions 18','empty-hand-pass'),
('Rest scans several Infected cards while no Larva was on your board. Can the scan kill you from multiple infected cards; when can Rest be fatal?', 'No; place one Larva regardless number infected. Can be fatal only if a Larva already was on board before Rest.', 'Actions 19','rest-multiple-infected'),
('You throw a Grenade/Molotov at uncarried Eggs in the Nest from a neighboring Room. Where is the required Noise roll resolved?', 'In the Character current Room, not the Nest.', 'Rooms 2','egg-grenade-noise-location'),
('Scientist uses Intranet to research an Object while carrying it outside the Laboratory. Can that reveal a Weakness?', 'No; Object itself must be in Laboratory, even when remote action used.', 'Rooms 3','remote-lab-object'),
('Storage Item Counter is zero. Can you use its Room Action repeatedly, and how is ordinary Search different?', 'Yes Room Action usable repeatedly paying cost, subject to normal restrictions. Counter only limits Search Action card; at zero normal Search cannot be used.', 'Rooms 6','storage-empty-counter'),
('When the Nest is on Fire and Vulnerability to Fire is discovered, how many of its Eggs are destroyed each Fire Damage step?', 'Two Eggs instead of normal one.', 'Rooms 7','nest-fire-weakness'),
('Take an Egg from the Intruder board and drop it back in the Nest Room. Does it restore the Nest Egg total for destruction purposes?', 'No; dropped Egg is a normal Heavy Object in Room and no longer counts toward Nest hit points.', 'Rooms 9','dropped-egg-nest-hp'),
('Smoke Grenade says each target loses one Action card. Who chooses and where does it go?', 'Each targeted player chooses one Action card from hand and discards it.', 'Items 1','smoke-grenade'),
('Can Medkit and Bandages be used on other Characters?', 'Yes, both.', 'Items 2','heal-others'),
('May you use your Energy Charge directly to reload another Character Weapon; what procedure permits that recharge?', 'No; Trade Charge to that Character, who uses it during own round.', 'Items 3','energy-charge-other'),
('Alcohol scans an Infected Contamination card. Does this place a Larva and what happens instead?', 'No Larva from this result; take a new Contamination card.', 'Items 4','alcohol-scan-exception'),
('Adding Extended Magazine or Auto Loader to an already-used or empty Energy Weapon: does it immediately provide extra Ammo?', 'Yes.', 'Items 5','attachment-ammo'),
('When you Craft a Flamethrower, does it start fully loaded or with the one Ammo of a searched Weapon?', 'Fully loaded.', 'Items 6','crafted-ammo'),
('Does the Hand Serious Wound affect Scout Motion Scanner and why?', 'No; unique reaction ability, not Item Action.', 'Items 7','motion-scanner'),
('Describe Antidote: scan scope, removed cards, new Contamination, reshuffling, hand retention and passing; how does Surgery differ?', 'Scan all Contamination from hand/deck/discard, remove all Infected from game, take one new Contamination, reshuffle it with all non-Infected scanned Contamination and Action cards except cards left in hand, then pass. May retain hand cards. Surgery instead shuffles entire hand too and does not gain extra Contamination (and its own wound/removal procedure still applies).', 'Items 9','antidote'),
('On exploration, where are Slime, Fire, Malfunction and Door effects placed, and which Corridor receives the Door?', 'Slime on Character board, Fire/Malfunction in explored Room, Door in Corridor used to enter. Resolve each token once then remove from game; general placement exceptions apply.', 'MANUAL 1454-1473','exploration-placement'),
('During the Event Phase Fire Damage step, how many Injuries does each Intruder in a burning Room take, when relative to attacks, and does it trigger an Injury Effect check?', 'Each takes one Injury after Intruder Attack step; place injury and resolve ordinary Injury Effect, including possible death/retreat.', 'MANUAL 750-764;1565-1566;1984-2001','intruder-fire-damage')
]
